const STATUS_CONFIG={"Сборка":{order:1,class:"sborka"},"Собран":{order:2,class:"sobran"},"На испытании":{order:3,class:"на-испытании"},"Испытан":{order:4,class:"испытан"},"На упаковке":{order:5,class:"на-упаковке"},"Упакован":{order:6,class:"упакован"}};async function loadDrafts(){try{const s=await fetch("/api/drafts?status=active"),n=await s.json(),t=document.getElementById("draftsList");if(n.success&&n.drafts.length>0){t.innerHTML="";const s=n.drafts.filter(s=>"Отгружен"!==s.machine_status);if(0===s.length)return void showEmptyState("📝","Нет активных станков","Все станки отгружены");sortDrafts(s).forEach(s=>{const n=createDraftElement(s);t.appendChild(n)})}else showEmptyState("📝","Нет станков в работе","Добавьте первый станок")}catch(s){showStatus(`Ошибка загрузки: ${s.message}`,"error")}}function createDraftElement(s){const n=document.createElement("div");n.className="draft-item",n.onclick=()=>viewDraft(s.id),n.style.cursor="pointer";const t=s.machine_status?s.machine_status.toLowerCase().replace(/\s+/g,"-"):"";let a="Не указана";if(s.shipping_date){const n=new Date(s.shipping_date);isNaN(n.getTime())||(a=n.toLocaleDateString("ru-RU",{day:"2-digit",month:"2-digit",year:"numeric"}))}return n.innerHTML=`\n        <div class="draft-header">\n            <div class="draft-title">\n                ${s.display_name}\n            </div>\n        </div>\n\n        <div class="draft-info">\n            <div class="info-item">\n                <span class="info-label">Тип работы:</span>\n                <span class="info-value">${s.work_type}</span>\n            </div>\n\n            <div class="info-item">\n                <span class="info-label">Заказчик:</span>\n                <span class="info-value">${s.customer||"Не указан"}</span>\n            </div>\n\n            <div class="info-item">\n                <span class="info-label">Статус:</span>\n                <span class="info-value status-value ${t}">\n                    ${s.machine_status}\n                </span>\n            </div>\n\n            <div class="info-item">\n                <span class="info-label">Отгрузка:</span>\n                <span class="info-value shipping-date">\n                    ${a}\n                </span>\n            </div>\n        </div>\n    `,n}function viewDraft(s){window.location.href=`/view-machine.html?id=${s}`}function sortDrafts(s){return s.sort((s,n)=>{const t=STATUS_CONFIG[s.machine_status]?.order||999,a=STATUS_CONFIG[n.machine_status]?.order||999;return t!==a?t-a:s.display_name.localeCompare(n.display_name)})}function showEmptyState(s,n,t){document.getElementById("draftsList").innerHTML=`\n        <div class="empty-state">\n            <div class="icon">${s}</div>\n            <h3>${n}</h3>\n            <p>${t}</p>\n            <a href="/add-draft" class="action-btn" style="max-width: 200px; margin-top: 15px;">\n                + Станок\n            </a>\n        </div>\n    `}function showStatus(s,n){const t=document.getElementById("statusMessage");t&&(t.textContent=s,t.className=`status-message ${n}`,t.style.display="block",setTimeout(()=>{t.style.display="none"},3e3))}document.addEventListener("DOMContentLoaded",()=>{loadDrafts()});